import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    idx += 1

    X = list(map(int, data[idx:idx+N]))
    idx += N

    Y = list(map(int, data[idx:idx+N]))
    idx += N

    Q = int(data[idx])
    idx += 1

    # Build the initial array A where A[i] = 1 if understaffed, 0 otherwise
    A = []
    for i in range(N):
        if Y[i] < X[i]:
            A.append(1)
        else:
            A.append(0)

    # Segment tree for range sum query
    size = 1
    while size < N:
        size *= 2
    tree = [0] * (2 * size)

    # Initialize the segment tree
    for i in range(N):
        tree[size + i] = A[i]
    for i in range(size - 1, 0, -1):
        tree[i] = tree[2 * i] + tree[2 * i + 1]

    def update(pos, value):
        p = size + pos
        tree[p] = value
        p //= 2
        while p >= 1:
            tree[p] = tree[2 * p] + tree[2 * p + 1]
            p //= 2

    def range_sum(l, r):
        # [l, r] inclusive, 0-indexed
        l += size
        r += size
        res = 0
        while l <= r:
            if l % 2 == 1:
                res += tree[l]
                l += 1
            if r % 2 == 0:
                res += tree[r]
                r -= 1
            l //= 2
            r //= 2
        return res

    output = []
    for _ in range(Q):
        op = int(data[idx])
        x = int(data[idx+1])
        y = int(data[idx+2])
        idx += 3

        if op == 1:
            # Increase employees in office x by y
            pos = x - 1
            Y[pos] += y
            if Y[pos] < X[pos]:
                update(pos, 1)
            else:
                update(pos, 0)
        elif op == 2:
            # Fire y people from office x
            pos = x - 1
            Y[pos] = max(0, Y[pos] - y)
            if Y[pos] < X[pos]:
                update(pos, 1)
            else:
                update(pos, 0)
        elif op == 3:
            # Check range [x, y]
            l = x - 1
            r = y - 1
            if l > r:
                l, r = r, l
            if l < 0:
                l = 0
            if r >= N:
                r = N - 1
            if l > r:
                s = 0
            else:
                s = range_sum(l, r)
            if s > 0:
                output.append("Understaffed offices present")
            else:
                output.append("All offices at full efficiency")

    for line in output:
        print(line)

if __name__ == "__main__":
    main()
